<?php if(!isset($manager,$user)){http_response_code(404);exit;}$mail=$app->mailConfig();$events=$manager->query('SELECT id,kind,status,attempts,next_attempt_at,last_error,created_at FROM notification_outbox ORDER BY id DESC LIMIT 100'); ?>
<?php if($user['role']==='admin'):?><section class="card"><h2>Email delivery settings</h2><p class="help">In simulation mode no emails are sent. Enter your mail provider's SMTP details, then enable real emails. A queued test email checks delivery to the notification address.</p><?php form_start('mail_settings','mail');select('mail_mode','Mode',['log'=>'Simulation — no email sent','smtp'=>'SMTP delivery'],$mail['mode']);input('smtp_host','SMTP hostname',$mail['host']);input('smtp_port','Port',$mail['port'],'number',true,'min="1" max="65535"');select('smtp_security','Encryption',['starttls'=>'STARTTLS (usually port 587)','tls'=>'TLS (usually port 465)'],$mail['security']);input('smtp_user','SMTP username',$mail['user']);input('smtp_password',$mail['password']?'SMTP password (saved; leave blank to keep)':'SMTP password','','password',false,'autocomplete="new-password"');input('mail_from','Sender email',$mail['from'],'email');input('admin_email','Staff notification email',$mail['admin'],'email');checkbox('mail_enabled','Enable real outgoing emails and approve this sender',(bool)$mail['approved']);?><button data-confirm="Save email settings? Enabling real email allows queued guest notifications to be delivered.">Save email settings</button></form><?php form_start('mail_test','mail');?><button class="secondary" data-confirm="Send a test email to the configured staff notification address?">Queue a test email</button></form></section><?php endif;?>
<section class="card"><h2>Latest email events</h2><p class="help">Current mode: <?=ae($mail['mode'])?>. Simulated messages will never be sent later. Failed messages can be retried. The worker runs once per minute.</p><div class="scroll"><table><thead><tr><th>Event</th><th>Status</th><th>Attempts</th><th>Created (UTC)</th><th>Action</th></tr></thead><tbody><?php foreach($events as $event):?><tr><td>#<?=(int)$event['id']?> <?=ae($event['kind'])?><small><?=ae($event['last_error'])?></small></td><td><span class="badge <?=ae($event['status'])?>"><?=ae($event['status'])?></span></td><td><?=(int)$event['attempts']?></td><td class="nowrap"><?=ae($event['created_at'])?></td><td><?php if($event['status']==='failed'):form_start('retry_mail','mail',['id'=>$event['id']]);?><button class="secondary" data-confirm="Retry delivery of this failed email?">Retry</button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></div><?php if(!$events):?><p class="empty">No email events yet.</p><?php endif;?></section>
